{"command": "cd /app && python -c "
import json
for q in ['q01','q02','q03','q04','q05']:
    d = json.load(open(f'/app/output/{q}.json'))
    if isinstance(d, list):
        if 'run_id' in d[0]:
            ids = [r['run_id'] for r in d]
        else:
            ids = [r['board_family'] for r in d]
        assert ids == sorted(ids), f'{q} not sorted'
        if q == 'q05':
            for r in d:
                assert r['runner_up_run_ids'] == sorted(r['runner_up_run_ids']), f'{q} runners'
    else:
        for key, val in d.items():
            if isinstance(val, list) and val and isinstance(val[0], str):
                assert val == sorted(val), f'{q} {key}'
            if isinstance(val, dict):
                keys = list(val.keys())
                assert keys == sorted(keys), f'{q} {key} nested'
    print(q, 'OK')
"", "security_risk": "LOW", "summary": "Verify sorting"}

